import sys

def main():
    balance = int(sys.stdin.readline().strip())

    for line in sys.stdin:
        line = line.strip()
        if line == 'q':
            break

        parts = line.split()
        if len(parts) >= 2:
            op = parts[0]
            val = float(parts[1])

            if op == '+=':
                balance += val
            elif op == '-=':
                balance -= val
            elif op == '*=':
                balance *= val
            elif op == '/=':
                balance = int(balance / val)
            elif op == '%=':
                balance = int(balance) % int(val)
            elif op == '&=':
                balance = int(balance) & int(val)
            elif op == '|=':
                balance = int(balance) | int(val)
            elif op == '^=':
                balance = int(balance) ^ int(val)
            elif op == '<<=':
                balance = int(balance) << int(val)
            elif op == '>>=':
                balance = int(balance) >> int(val)
            elif op == '=':
                balance = int(val)

    if balance != int(balance):
        balance = int(round(balance))

    print(f"Final Balance: {int(balance)}")

if __name__ == "__main__":
    main()
